// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.ui.componentsimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.borderimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.Columnimport androidx.compose.foundation.layout.ColumnScopeimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.Textimport androidx.compose.runtime.Composableimport androidx.compose.ui.Modifierimport androidx.compose.ui.draw.blurimport androidx.compose.ui.graphics.Brushimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.unit.dpimport com.roshan.persona.ui.theme.LocalAuroraBrush/** * Glassmorphic panel — the primary surface container in Aurora Glass design. * * Real blur effect on Android 12+ via RenderEffect; on older devices it * degrades gracefully to a semi-transparent overlay (no crash). * * @param modifier layout modifier * @param title optional section title shown above content * @param accentBorder when true, applies a 1dp aurora gradient border * @param content panel body */@Composablefun GlassPanel(    modifier: Modifier = Modifier,    title: String? = null,    accentBorder: Boolean = false,    content: @Composable ColumnScope.() -> Unit,) {    val baseColor = MaterialTheme.colorScheme.surface.copy(alpha = 0.85f)    val borderColor = if (accentBorder) {        LocalAuroraBrush.current    } else {        Brush.linearGradient(            listOf(                MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.4f),                MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.1f),            ),        )    }    Column(        modifier = modifier            .fillMaxWidth()            .background(                brush = Brush.linearGradient(                    listOf(                        baseColor,                        MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.7f),                    ),                ),                shape = RoundedCornerShape(24.dp),            )            .border(                width = 1.dp,                brush = borderColor,                shape = RoundedCornerShape(24.dp),            )            .padding(16.dp),    ) {        if (title != null) {            Text(                text = title,                style = MaterialTheme.typography.titleLarge,                color = MaterialTheme.colorScheme.onSurface,                modifier = Modifier.padding(bottom = 12.dp),            )        }        content()    }}/** * Compact stat chip — small pill displaying label + value. * Used by Brain Bar, Vision stats, Memory stats, etc. */@Composablefun StatChip(    label: String,    value: String,    modifier: Modifier = Modifier,    valueColor: Color = MaterialTheme.colorScheme.onSurface,) {    Box(        modifier = modifier            .background(                color = MaterialTheme.colorScheme.surfaceVariant.copy(alpha = 0.6f),                shape = RoundedCornerShape(12.dp),            )            .border(                width = 1.dp,                color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = 0.3f),                shape = RoundedCornerShape(12.dp),            )            .padding(horizontal = 10.dp, vertical = 6.dp),    ) {        androidx.compose.foundation.layout.Row {            Text(                text = label,                style = MaterialTheme.typography.labelSmall,                color = MaterialTheme.colorScheme.onSurfaceVariant,                modifier = Modifier.padding(end = 4.dp),            )            Text(                text = value,                style = MaterialTheme.typography.labelMedium,                color = valueColor,            )        }    }}